import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for TokenBuffer.writeEndArray().
 */
public class TokenBuffer_writeEndArray_TriageGen0Test {

    private ObjectMapper mapper;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
    }



    @Test
    public void testWriteEndArray_NestedArray() throws IOException {
        TokenBuffer buffer = new TokenBuffer(mapper);

        // Structure: [ [ 1 ] ]
        buffer.writeStartArray(); // Outer
        buffer.writeStartArray(); // Inner
        buffer.writeNumber(1);
        buffer.writeEndArray();   // Close Inner
        buffer.writeEndArray();   // Close Outer (the method being tested)

        JsonParser parser = buffer.asParser();

        // Check Outer Array
        assertEquals(JsonToken.START_ARRAY, parser.nextToken());

        // Check Inner Array
        assertEquals(JsonToken.START_ARRAY, parser.nextToken());
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(1, parser.getIntValue());
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());

        // Check Outer End
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());
        assertEquals(JsonToken.NOT_AVAILABLE, parser.nextToken());
    }




}

